1045:     const oldX = actor.x, oldY = actor.y;
1046:     const steps = Math.max(1, Math.ceil(Math.hypot(dx, dy) / 4));
1047:     const stepX = dx / steps, stepY = dy / steps;
1048:     let hitX = false, hitY = false;
1049:     for (let step = 0; step < steps; step++) {
1050:       const x = actor.x, y = actor.y;
1051:       const nextX = x + stepX, nextY = y + stepY;
1052:       if (!blocked(nextX, nextY, radius)) {
1053:         actor.x = nextX; actor.y = nextY;
1054:         actor.safeX = actor.x; actor.safeY = actor.y;
1055:         continue;
1056:       }
1057: 
1058:       // Try both axes independently so a collision on one side never cancels sliding on the other.
1059:       const axes = Math.abs(stepX) >= Math.abs(stepY) ? ['x', 'y'] : ['y', 'x'];
1060:       let moved = false;
1061:       for (const axis of axes) {
1062:         const candidateX = actor.x + (axis === 'x' ? stepX : 0);
1063:         const candidateY = actor.y + (axis === 'y' ? stepY : 0);
1064:         if (!blocked(candidateX, candidateY, radius)) {
1065:           actor.x = candidateX; actor.y = candidateY;
1066:           if (axis === 'x') hitY = true; else hitX = true;
1067:           moved = true;
1068:         }
1069:       }
1070: 
1071:       // At rounded corners, project the remaining motion onto a nearby circle's tangent.
1072:       if (!moved) {
1073:         let best = null, bestProgress = 0;
1074:         for (const obstacle of colliders) {
1075:           let nx = x - obstacle.x, ny = y - obstacle.y;
1076:           const distance = Math.hypot(nx, ny) || 1;
1077:           const reach = radius + obstacle.r;
1078:           if (distance > reach + 6) continue;
