1080:           const intoSurface = stepX * nx + stepY * ny;
1081:           if (intoSurface >= 0) continue;
1082:           const tangentX = stepX - nx * intoSurface;
1083:           const tangentY = stepY - ny * intoSurface;
1084:           const candidateX = x + tangentX, candidateY = y + tangentY;
1085:           const progress = tangentX * stepX + tangentY * stepY;
1086:           if (progress > bestProgress && !blocked(candidateX, candidateY, radius)) {
1087:             best = { x: candidateX, y: candidateY };
1088:             bestProgress = progress;
1089:           }
1090:         }
1091:         if (best) { actor.x = best.x; actor.y = best.y; moved = true; }
1092:       }
1093:       if (!moved) { hitX = true; hitY = true; }
1094:       if (!blocked(actor.x, actor.y, radius)) { actor.safeX = actor.x; actor.safeY = actor.y; }
1095:     }
1096: 
1097:     if (hitX && actor.vx * dx > 0) actor.vx = 0;
1098:     if (hitY && actor.vy * dy > 0) actor.vy = 0;
1099:     if (actor.x === oldX) actor.vx *= 0.15;
1100:     if (actor.y === oldY) actor.vy *= 0.15;
